using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Demo6.Game;using Newtonsoft.Json;
public static class SetupImportedFxV056 {
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play before catalog setup");const string path="Assets/Resources/ImportedFxV056/catalog.asset";Directory.CreateDirectory("Assets/Resources/ImportedFxV056");var c=AssetDatabase.LoadAssetAtPath<ImportedFxV056Catalog>(path);if(!c)c=ScriptableObject.CreateInstance<ImportedFxV056Catalog>();const string root="Assets/Effects/Game/ImportedCandidates/Demo6_";c.hitSparks=AssetDatabase.LoadAssetAtPath<GameObject>(root+"HitSparks_Compact.prefab");c.groundDust=AssetDatabase.LoadAssetAtPath<GameObject>(root+"GroundDust_Compact.prefab");c.stoneDebris=AssetDatabase.LoadAssetAtPath<GameObject>(root+"StoneDebris_Compact.prefab");if(!c.hitSparks||!c.groundDust||!c.stoneDebris)throw new Exception("Candidate import missing");if(!AssetDatabase.Contains(c))AssetDatabase.CreateAsset(c,path);EditorUtility.SetDirty(c);AssetDatabase.SaveAssets();var result=new[]{c.hitSparks,c.groundDust,c.stoneDebris}.Select(g=>new{name=g.name,systems=g.GetComponentsInChildren<ParticleSystem>(true).Length,materials=g.GetComponentsInChildren<ParticleSystemRenderer>(true).Select(r=>new{shader=r.sharedMaterial.shader.name,supported=r.sharedMaterial.shader.isSupported}).ToArray()}).ToArray();Directory.CreateDirectory("검증/v056-fx");File.WriteAllText("검증/v056-fx/import.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
